def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def ranges(size, separators):
        result = []
        start = 0
        for i in separators:
            if start < i:
                result.append((start, i))
            start = i + 1
        if start < size:
            result.append((start, size))
        return result

    rows = ranges(h, sep_rows)
    cols = ranges(w, sep_cols)
    panels = []
    for r0, r1 in rows:
        for c0, c1 in cols:
            count = sum(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1))
            panels.append((count, r0, r1, c0, c1))

    _, sr0, sr1, sc0, sc1 = max(panels)
    out = [row[:] for row in grid]
    for _, r0, r1, c0, c1 in panels:
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = grid[sr0 + (r - r0)][sc0 + (c - c0)]
    return out
